BEGIN;
CREATE TEMP TABLE history_fixture AS SELECT user_id owner_id,partner_user_id partner_id,gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() t,gen_random_uuid() doc FROM partner_links WHERE status='active' LIMIT 1;
GRANT SELECT ON history_fixture TO authenticated;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM history_fixture) THEN RAISE EXCEPTION 'Active pair required'; END IF; END $$;
INSERT INTO accounts(id,user_id,name,type,currency,current_balance) SELECT a,owner_id,'History fixture','checking','USD',100 FROM history_fixture UNION ALL SELECT b,owner_id,'New history fixture','checking','USD',200 FROM history_fixture;
INSERT INTO transactions(id,user_id,account_id,name,date,amount,category) SELECT t,owner_id,a,'History fixture',current_date-20,50,'Food' FROM history_fixture;
SET LOCAL ROLE authenticated;
DO $$ DECLARE f record;blocked boolean; BEGIN SELECT * INTO f FROM history_fixture;PERFORM set_config('request.jwt.claim.sub',f.owner_id::text,true);
 PERFORM finance_share_account(f.a,true,current_date-30,NULL);
 PERFORM finance_link_account_history(f.a,f.b,current_date-10);
 UPDATE accounts SET is_deleted=true,current_balance=0 WHERE id=f.a;
 IF (SELECT current_balance FROM accounts WHERE id=f.a)<>100 THEN RAISE EXCEPTION 'Archived balance erased';END IF;
 PERFORM finance_transaction_history(f.a,current_date-10,100,50,true,'Continuity fixture');
 IF NOT EXISTS(SELECT 1 FROM transactions WHERE id=f.t) THEN RAISE EXCEPTION 'Transaction disappeared';END IF;
 UPDATE transactions SET amount=55 WHERE id=f.t;
 IF NOT EXISTS(SELECT 1 FROM finance_transaction_versions WHERE transaction_id=f.t AND (record->>'amount')::numeric=50) THEN RAISE EXCEPTION 'Prior revision lost';END IF;
 INSERT INTO finance_documents(id,owner_id,kind,name,payload) VALUES(f.doc,f.owner_id,'close','Test close','{}');
 DELETE FROM finance_documents WHERE id=f.doc;UPDATE finance_documents SET name='Changed' WHERE id=f.doc;
 IF NOT EXISTS(SELECT 1 FROM finance_documents WHERE id=f.doc AND name='Test close') THEN RAISE EXCEPTION 'Close was mutable';END IF;
 PERFORM finance_share_account(f.a,false,NULL,NULL);
 PERFORM set_config('request.jwt.claim.sub',f.partner_id::text,true);
 IF NOT EXISTS(SELECT 1 FROM finance_retained_history WHERE account_id=f.a AND payload->'transactions'->0->>'id'=f.t::text) THEN RAISE EXCEPTION 'Shared history not retained';END IF;
 IF EXISTS(SELECT 1 FROM accounts WHERE id=f.a) THEN RAISE EXCEPTION 'Live access not revoked';END IF;
 IF EXISTS(SELECT 1 FROM finance_transaction_versions WHERE transaction_id=f.t) THEN RAISE EXCEPTION 'Owner audit exposed';END IF;
 blocked:=false;BEGIN PERFORM finance_link_account_history(f.a,f.b,current_date);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Another owner linked accounts';END IF;
 blocked:=false;BEGIN PERFORM finance_retain_shared(f.a,f.partner_id,'0001-01-01');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Private retention callable';END IF;
END $$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: archival, transaction revision audit, immutable closes, retained shared history, revoked live access, owner isolation and protected retention. Fixtures rolled back.' AS result;
